#!/usr/bin/env python3
"""Mod Builder eval runner. Runs ON THE BUILD VM (talks to 127.0.0.1:7340).

  python3 run_eval.py <tag> [--only key1,key2] [--prompts prompts.jsonl] [--out DIR]

Submits every prompt in prompts.jsonl as build id ev-<tag>-<key>, waits for all
of them (the service queues them at its own concurrency), and writes
  <out>/<tag>/results.jsonl   one line per prompt
  <out>/<tag>/jars/<key>.jar  artifacts of builds marked rt (runtime check subset)
Re-running with the same tag reuses finished builds (ids are idempotent).
Summarise with summarize.py; runtime-load the jars with rtcheck.py.
"""
import json, os, sys, time, urllib.request, argparse

ap = argparse.ArgumentParser()
ap.add_argument("tag")
ap.add_argument("--only", default="")
ap.add_argument("--prompts", default=os.path.join(os.path.dirname(os.path.abspath(__file__)), "prompts.jsonl"))
ap.add_argument("--out", default="/root/mbeval")
ap.add_argument("--url", default="http://127.0.0.1:7340")
a = ap.parse_args()

KEY = ""
for line in open("/root/modbuilder.env"):
    if line.startswith("MODBUILDER_API_KEY="):
        KEY = line.split("=", 1)[1].strip()
H = {"Authorization": f"Bearer {KEY}", "Content-Type": "application/json"}


def req(method, path, body=None, raw=False):
    r = urllib.request.Request(a.url + path, method=method, headers=H, data=json.dumps(body).encode() if body is not None else None)
    with urllib.request.urlopen(r, timeout=60) as resp:
        data = resp.read()
    return data if raw else json.loads(data)


prompts = [json.loads(l) for l in open(a.prompts) if l.strip()]
if a.only:
    want = set(a.only.split(","))
    prompts = [p for p in prompts if p["key"] in want]
outdir = os.path.join(a.out, a.tag)
os.makedirs(os.path.join(outdir, "jars"), exist_ok=True)

ids = {}
for p in prompts:
    bid = f"ev-{a.tag}-{p['key']}"[:64]
    ids[p["key"]] = bid
    r = req("POST", "/builds", {"id": bid, "prompt": p["prompt"], "mcVersion": p["v"]})
    print("submitted", bid, r.get("status"), flush=True)

pending = set(ids)
recs = {}
while pending:
    time.sleep(15)
    for k in sorted(pending):
        r = req("GET", f"/builds/{ids[k]}")
        if r["status"] in ("succeeded", "failed"):
            recs[k] = r
            pending.discard(k)
            print(f"done {k}: {r['status']} {r.get('errorCode') or ''} attempts={r['attempts']} ${r['costUsd']} {r['durationMs']//1000}s", flush=True)

with open(os.path.join(outdir, "results.jsonl"), "w") as f:
    for p in prompts:
        r = recs[p["key"]]
        calls = r.get("aiCalls") or []
        line = {
            "key": p["key"], "v": p["v"], "cls": p["cls"], "rt": p.get("rt", False), "adversarial": p.get("adversarial", False),
            "id": r["id"], "status": r["status"], "errorCode": r.get("errorCode"), "attempts": r["attempts"], "repairs": r.get("repairs", 0),
            "costUsd": r["costUsd"], "durationMs": r["durationMs"], "route": (r.get("route") or {}).get("class"),
            "routeInfo": r.get("route"), "calls": [{k2: c.get(k2) for k2 in ("kind", "route", "model", "resolvedModel", "costUsd", "turns", "durationMs", "subtype")} for c in calls],
            "plugin": r.get("pluginName"), "warnings": r.get("warnings"), "precheck": r.get("precheck"),
            "errorDetail": (r.get("errorDetail") or "")[:1500],
            "repairErrors": [e.get("detail", "")[:1500] for e in r.get("events", []) if e.get("detail")],
        }
        f.write(json.dumps(line) + "\n")
        if p.get("rt") and r["status"] == "succeeded":
            open(os.path.join(outdir, "jars", f"{p['key']}.jar"), "wb").write(req("GET", f"/builds/{r['id']}/artifact", raw=True))
print("wrote", os.path.join(outdir, "results.jsonl"))
#!/usr/bin/env python3
"""Compare eval runs. python3 summarize.py <tag> [<tag> ...] [--root /root/mbeval]
Prints one markdown table per tag set: overall + by route class (the route the
improved service chose; for runs without routing, the prompt's labelled class)."""
import json, os, sys, statistics as st

args = [x for x in sys.argv[1:] if not x.startswith("--")]
root = "/root/mbeval"
if "--root" in sys.argv:
    root = sys.argv[sys.argv.index("--root") + 1]
    args = [x for x in args if x != root]


def load(tag):
    rows = [json.loads(l) for l in open(os.path.join(root, tag, "results.jsonl"))]
    rt = {}
    p = os.path.join(root, tag, "rt.jsonl")
    if os.path.exists(p):
        for l in open(p):
            r = json.loads(l)
            rt[r["key"]] = r
    return rows, rt


def stats(rows, rt):
    if not rows:
        return None
    ok = [r for r in rows if r["status"] == "succeeded"]
    costs = [r["costUsd"] for r in rows]
    rtk = [rt[r["key"]] for r in rows if r["key"] in rt]
    rt_total = len([r for r in rows if r.get("rt")])
    models = {}
    for r in rows:
        for c in r["calls"]:
            m = c.get("resolvedModel") or c.get("model")
            models[m] = models.get(m, 0) + (c.get("costUsd") or 0)
    return {
        "n": len(rows), "ok": len(ok), "rate": len(ok) / len(rows),
        "avg": sum(costs) / len(costs), "med": st.median(costs), "total": sum(costs),
        "repairs": sum(r["repairs"] for r in rows) / len(rows),
        "first": sum(1 for r in ok if r["repairs"] == 0) / len(rows),
        "time": sum(r["durationMs"] for r in rows) / len(rows) / 1000,
        "medtime": st.median([r["durationMs"] for r in rows]) / 1000,
        "rt": f"{sum(1 for x in rtk if x['ok'])}/{rt_total}" if rt_total else "-",
        "models": ", ".join(f"{m}: ${v:.2f}" for m, v in sorted(models.items(), key=lambda x: -x[1]) if m),
    }


def line(label, s):
    if not s:
        return f"| {label} | - |"
    return (f"| {label} | {s['ok']}/{s['n']} ({s['rate']:.0%}) | {s['first']:.0%} | ${s['avg']:.3f} | ${s['med']:.3f} | ${s['total']:.2f} | "
            f"{s['repairs']:.2f} | {s['time']:.0f}s / {s['medtime']:.0f}s | {s['rt']} |")


print("| run / slice | success | first-try | avg cost | median cost | total | repairs/build | avg / median time | runtime ok |")
print("|---|---|---|---|---|---|---|---|---|")
for tag in args:
    rows, rt = load(tag)
    normal = [r for r in rows if not r["adversarial"]]
    adv = [r for r in rows if r["adversarial"]]
    print(line(f"**{tag}** all non-adversarial", stats(normal, rt)))
    for cls in ("simple", "standard", "complex"):
        sl = [r for r in normal if (r.get("route") or r["cls"]) == cls]
        print(line(f"{tag} route={cls}", stats(sl, rt)))
    for v in ("1.21.1", "1.21.4", "1.21.8", "1.21.11"):
        sl = [r for r in normal if r["v"] == v]
        print(line(f"{tag} v{v}", stats(sl, rt)))
    print(f"| {tag} adversarial | {sum(1 for r in adv if r['errorCode'] == 'refused')}/{len(adv)} refused | | ${sum(r['costUsd'] for r in adv):.3f} total | | | | | |")
print()
for tag in args:
    rows, rt = load(tag)
    s = stats([r for r in rows if not r["adversarial"]], rt)
    print(f"- {tag} spend by model: {s['models']}")
    fails = [r for r in rows if r["status"] != "succeeded" and not r["adversarial"]]
    for r in fails:
        print(f"  - FAILED {r['key']} ({r['v']}): {r['errorCode']} {r['errorDetail'][:300]!r}")
    for k, x in rt.items():
        if not x["ok"]:
            print(f"  - RUNTIME {k} ({x['v']}): enabled={x['enabled']} enableError={x['enableError']} {x['exceptions'][:2]}")
