#!/usr/bin/env python3
"""Cyrus eval set: loader, per-version matrix expansion and validator. Pure, no network, no model.

  python3 evalset.py --list [--json]        every prompt (id, category, route, versions, flags)
  python3 evalset.py --matrix [--avg-cost USD]   the (prompt, version) pairs per version, with counts
  python3 evalset.py --validate             check every prompt file + matrix.json; exit 1 on a problem

Files: prompts.jsonl (the original 28 + 2 adversarial, never edited), sets/*.jsonl (new), matrix.json,
and ../../../lib/cyrus/versions/registry.json (versions; optional here, the checks that need it are skipped
with a warning when it is not next to the eval dir, e.g. on the build VM).
Imported by run_eval.py and report.py.
"""
import glob, json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
REGISTRY = os.environ.get("EVAL_REGISTRY") or os.path.join(HERE, "..", "..", "..", "lib", "cyrus", "versions", "registry.json")
RULES = os.path.join(HERE, "..", "rules", "failure-rules.json")
REQUIRED = ("key", "v", "cls", "prompt", "category", "route", "checks", "must_refuse")


def load_matrix():
    return json.load(open(os.path.join(HERE, "matrix.json")))


def load_registry():
    try:
        return {v["id"]: v for v in json.load(open(REGISTRY))["versions"]}
    except OSError:
        return None


def _read(path):
    return [json.loads(l) for l in open(path) if l.strip()]


def load_legacy(matrix=None):
    """The original prompts, normalised with the matrix.json overlay (the file itself is untouched)."""
    matrix = matrix or load_matrix()
    out = []
    for p in _read(os.path.join(HERE, "prompts.jsonl")):
        meta = matrix["legacy"]["prompts"].get(p["key"], {})
        q = {"adversarial": False, "rt": False, **p, **meta}
        q["legacy"] = True
        out.append(q)
    return out


def load_new():
    out = []
    for f in sorted(glob.glob(os.path.join(HERE, "sets", "*.jsonl"))):
        for p in _read(f):
            p["_file"] = os.path.basename(f)
            out.append(p)
    return out


def load_all(matrix=None):
    matrix = matrix or load_matrix()
    return load_legacy(matrix) + load_new()


def effective_versions(p, matrix):
    return p.get("versions") or [v["id"] for v in matrix["versions"]]


def expand(prompts, matrix, only_versions=None):
    """[(version_row, prompt)] in matrix order. 'all' = every prompt that includes the version; 'core' = matrix core keys."""
    core = set(matrix["core"])
    pairs = []
    for vr in matrix["versions"]:
        if only_versions and vr["id"] not in only_versions:
            continue
        for p in prompts:
            if vr["id"] not in effective_versions(p, matrix):
                continue
            if vr["select"] == "core" and p["key"] not in core:
                continue
            pairs.append((vr, p))
    return pairs


def validate():
    """Returns a list of problem strings (empty = ok), plus warnings."""
    problems, warnings = [], []
    try:
        matrix = load_matrix()
    except Exception as e:
        return [f"matrix.json: {e}"], []
    reg = load_registry()
    if reg is None:
        warnings.append("registry.json not found: version/buildable checks skipped")
    try:
        prompts = load_all(matrix)
    except Exception as e:
        return [f"prompt files: {e}"], warnings
    keys = [p.get("key") for p in prompts]
    for k in sorted({k for k in keys if keys.count(k) > 1}):
        problems.append(f"duplicate key {k}")
    byk = {p["key"]: p for p in prompts if "key" in p}
    vocab = set(matrix["checks"])
    routes = set(matrix["routes"])
    for p in prompts:
        k = p.get("key", "?")
        for f in REQUIRED:
            if f not in p:
                problems.append(f"{k}: missing {f}")
        if not isinstance(p.get("prompt"), str) or len(p.get("prompt", "")) < 20:
            problems.append(f"{k}: prompt text too short")
        if p.get("category") not in matrix["categories"]:
            problems.append(f"{k}: unknown category {p.get('category')}")
        if p.get("route") not in routes:
            problems.append(f"{k}: unknown route {p.get('route')}")
        for c in p.get("checks", []):
            if c not in vocab:
                problems.append(f"{k}: unknown check {c}")
        if p.get("must_refuse") and not (p.get("adversarial") and p.get("route") == "none" and "refused" in p.get("checks", [])):
            problems.append(f"{k}: must_refuse needs adversarial=true, route=none, check 'refused'")
        if p.get("category") == "unsafe" and not (p.get("must_refuse") or p.get("constrain")):
            problems.append(f"{k}: unsafe prompt must be must_refuse or carry a `constrain` note")
        if p.get("category") != "unsafe" and p.get("must_refuse"):
            problems.append(f"{k}: must_refuse outside the unsafe category")
        if p.get("category") == "asset":
            tier = p.get("tier")
            if tier not in matrix["assetTiers"]:
                problems.append(f"{k}: asset prompt needs a tier")
            elif p.get("minPlan") != matrix["assetTiers"][tier]["minPlan"]:
                problems.append(f"{k}: minPlan does not match tier {tier}")
            if not isinstance(p.get("assetKinds"), list):
                problems.append(f"{k}: asset prompt needs assetKinds")
            if p.get("route") == "none":
                problems.append(f"{k}: asset prompt needs a real route")
        if p.get("category") == "change" and p.get("baseKey") not in byk:
            problems.append(f"{k}: baseKey {p.get('baseKey')} is not a prompt")
        if "versions" in p and "1.21.11" not in p["versions"]:
            problems.append(f"{k}: versions must include 1.21.11")
        if reg is not None:
            for v in [p.get("v")] + list(p.get("versions", [])):
                if v not in reg:
                    problems.append(f"{k}: version {v} not in the registry")
    # known-rule bug-fix prompts
    try:
        rules = {r["id"]: r for r in json.load(open(RULES))["rules"]}
    except OSError:
        rules = None
    for p in prompts:
        if p.get("category") == "bugfix":
            r = (rules or {}).get(p.get("rule"))
            if rules is not None and not r:
                problems.append(f"{p['key']}: rule {p.get('rule')} not in failure-rules.json")
            elif r and "*" not in r["versions"] and p["v"] not in r["versions"]:
                problems.append(f"{p['key']}: rule {p['rule']} does not apply to {p['v']}")
    # matrix
    ids = [v["id"] for v in matrix["versions"]]
    if len(set(ids)) != len(ids):
        problems.append("matrix: duplicate version")
    for vr in matrix["versions"]:
        if reg is None:
            continue
        rv = reg.get(vr["id"])
        if not rv:
            problems.append(f"matrix: version {vr['id']} not in the registry")
        elif vr["role"] == "required" and not rv.get("buildable"):
            problems.append(f"matrix: {vr['id']} is required but not buildable")
        elif vr["role"] == "preview" and rv.get("buildable"):
            warnings.append(f"matrix: {vr['id']} is buildable now: consider promoting it from preview to required")
    for k in matrix["core"]:
        if k not in byk:
            problems.append(f"matrix core: unknown key {k}")
    for cat, spec in matrix["categories"].items():
        n = sum(1 for p in prompts if p.get("category") == cat)
        if n < spec["min"]:
            problems.append(f"category {cat}: {n} prompts, need {spec['min']}")
    if len(prompts) < matrix["minTotal"]:
        problems.append(f"total {len(prompts)} prompts, need {matrix['minTotal']}")
    return problems, warnings


def _print_matrix(avg_cost=None):
    matrix = load_matrix()
    prompts = load_all(matrix)
    reg = load_registry() or {}
    total_req = 0
    print(f"{len(prompts)} prompts; matrix over {len(matrix['versions'])} versions")
    print(f"{'version':9} {'role':8} {'select':6} {'builds':>6}  note")
    for vr in matrix["versions"]:
        pairs = expand(prompts, matrix, [vr["id"]])
        n = len(pairs)
        refuse = sum(1 for _, p in pairs if p.get("must_refuse"))
        buildable = reg.get(vr["id"], {}).get("buildable")
        tag = "buildable" if buildable else ("NOT buildable" if buildable is False else "?")
        if vr["role"] == "required":
            total_req += n - refuse * 0
        print(f"{vr['id']:9} {vr['role']:8} {vr['select']:6} {n:>6}  {tag}; {refuse} must-refuse; categories: " +
              ", ".join(f"{c}={sum(1 for _, p in pairs if p['category'] == c)}" for c in matrix["categories"]))
    print(f"required-version builds in a full matrix run: {total_req}")
    if avg_cost is not None:
        print(f"estimated cost at ${avg_cost:.2f}/build: ${total_req * avg_cost:.2f} (a single pass; asset/change prompts are skipped by run_eval until the router and project flow exist)")
    print("per category:", ", ".join(f"{c}={sum(1 for p in prompts if p['category'] == c)}" for c in matrix["categories"]))


def main(argv):
    if "--validate" in argv:
        problems, warnings = validate()
        for w in warnings:
            print("warning:", w)
        for p in problems:
            print("PROBLEM:", p)
        print("eval set ok" if not problems else f"{len(problems)} problem(s)")
        return 1 if problems else 0
    if "--matrix" in argv:
        ac = float(argv[argv.index("--avg-cost") + 1]) if "--avg-cost" in argv else None
        _print_matrix(ac)
        return 0
    if "--list" in argv:
