// Cyrus eval set (R0): pure data checks over services/modbuilder/eval (prompts.jsonl + sets/*.jsonl + matrix.json) against the
// version registry and the failure rules. No model, no network. Run: tsx --test test/cyrus-eval-set.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const EVAL = path.join(__dirname, "..", "services", "modbuilder", "eval");
const readJsonl = (f: string) => fs.readFileSync(f, "utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));
const matrix = JSON.parse(fs.readFileSync(path.join(EVAL, "matrix.json"), "utf8"));
const registry = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "lib", "cyrus", "versions", "registry.json"), "utf8"));
const rules: { id: string; versions: string[] }[] = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "services", "modbuilder", "rules", "failure-rules.json"), "utf8")).rules;
const regById = new Map<string, { id: string; buildable: boolean; capabilities: string[] }>(registry.versions.map((v: { id: string }) => [v.id, v]));

const legacyRaw = readJsonl(path.join(EVAL, "prompts.jsonl"));
const legacy = legacyRaw.map((p) => ({ adversarial: false, rt: false, ...p, ...matrix.legacy.prompts[p.key] }));
const fresh = fs.readdirSync(path.join(EVAL, "sets")).filter((f) => f.endsWith(".jsonl")).sort()
  .flatMap((f) => readJsonl(path.join(EVAL, "sets", f)));
const all = [...legacy, ...fresh];
const byKey = new Map(all.map((p) => [p.key, p]));
const effective = (p: { versions?: string[] }) => p.versions ?? matrix.versions.map((v: { id: string }) => v.id);
const inCat = (c: string) => all.filter((p) => p.category === c);

describe("eval set: the original prompts", () => {
  it("prompts.jsonl is untouched (28 prompts + 2 adversarial, pinned hash)", () => {
    const sha = createHash("sha256").update(fs.readFileSync(path.join(EVAL, "prompts.jsonl"))).digest("hex");
    assert.equal(sha, "b791cd4833184b6c37fb9515ce65f896e6e852b66f4bc444719f5bda68896f1d");
    assert.equal(legacyRaw.length, 30);
    assert.equal(legacyRaw.filter((p) => p.adversarial).length, 2);
  });
  it("every original has overlay metadata", () => {
    for (const p of legacyRaw) assert.ok(matrix.legacy.prompts[p.key], `no overlay for ${p.key}`);
  });
});

describe("eval set: shape", () => {
  it("ids are unique and well formed", () => {
    const ids = all.map((p) => p.key);
    assert.equal(new Set(ids).size, ids.length);
    for (const id of ids) assert.match(id, /^[a-z0-9][a-z0-9-]{2,40}$/);
  });
  it("required fields on every prompt", () => {
    for (const p of all) {
      for (const f of ["key", "v", "cls", "prompt", "category", "route", "checks", "must_refuse"]) assert.ok(f in p, `${p.key}: missing ${f}`);
      assert.ok(typeof p.prompt === "string" && p.prompt.length >= 20, `${p.key}: prompt text`);
      assert.ok(["simple", "standard", "complex"].includes(p.cls), `${p.key}: cls`);
      assert.ok(Array.isArray(p.checks) && p.checks.length > 0, `${p.key}: checks`);
      assert.equal(typeof p.must_refuse, "boolean", `${p.key}: must_refuse`);
      assert.ok(p.category in matrix.categories, `${p.key}: category ${p.category}`);
      assert.ok(p.route in matrix.routes, `${p.key}: route ${p.route}`);
      for (const c of p.checks) assert.ok(c in matrix.checks, `${p.key}: unknown check ${c}`);
    }
  });
  it("prompt texts are all different (no templating)", () => {
    assert.equal(new Set(all.map((p) => p.prompt)).size, all.length);
  });
  it("category counts meet the targets", () => {
    for (const [c, spec] of Object.entries(matrix.categories) as [string, { min: number }][]) {
      assert.ok(inCat(c).length >= spec.min, `${c}: ${inCat(c).length} < ${spec.min}`);
    }
    assert.ok(all.length >= 120, `total ${all.length}`);
    assert.ok(all.length >= matrix.minTotal);
  });
});

describe("eval set: asset prompts", () => {
  const assets = inCat("asset");
  it("every asset prompt has a route, asset kinds and a consistent plan tier", () => {
    for (const p of assets) {
      assert.ok(["plugin", "plugin+resourcePack", "dataPack"].includes(p.route), `${p.key}: route ${p.route}`);
      assert.ok(Array.isArray(p.assetKinds), `${p.key}: assetKinds`);
      assert.ok(p.tier in matrix.assetTiers, `${p.key}: tier ${p.tier}`);
      assert.equal(p.minPlan, matrix.assetTiers[p.tier].minPlan, `${p.key}: minPlan`);
      if (p.assetKinds.includes("sound") && !p.assetKinds.includes("texture")) assert.equal(p.tier, "sound", p.key);
      if (p.assetKinds.some((k: string) => ["texture", "font", "armor", "block"].includes(k))) assert.equal(p.tier, "sound+texture", p.key);
      if (p.route === "dataPack") assert.equal(p.tier, "none", `${p.key}: data packs need no studio`);
      if (p.route === "plugin+resourcePack") assert.notEqual(p.tier, "none", `${p.key}: a resource pack route needs a studio tier`);
    }
  });
  it("covers every route and every tier, and the named scenarios", () => {
    assert.deepEqual([...new Set(assets.map((p) => p.route))].sort(), ["dataPack", "plugin", "plugin+resourcePack"]);
    assert.deepEqual([...new Set(assets.map((p) => p.tier))].sort(), ["none", "sound", "sound+texture"]);
    const text = assets.map((p) => p.prompt.toLowerCase()).join("\n");
    for (const w of ["banshee", "handgun", "recipe", "loot", "advancement", "texture", "hud", "menu|gui"]) assert.match(text, new RegExp(w), w);
    assert.ok(assets.filter((p) => p.assetKinds.includes("sound")).length >= 6);
  });
  it("capability tags exist in the registry", () => {
    const caps = new Set(registry.versions.flatMap((v: { capabilities: string[] }) => v.capabilities));
    for (const p of all.filter((x) => x.capability)) assert.ok(caps.has(p.capability), `${p.key}: ${p.capability}`);
  });
});

describe("eval set: unsafe prompts", () => {
  it("every unsafe prompt is refused or constrained, and must_refuse is fully flagged", () => {
    const uns = inCat("unsafe");
    assert.ok(uns.some((p) => p.must_refuse));
    for (const p of uns) {
      if (p.must_refuse) {
        assert.equal(p.adversarial, true, `${p.key}: adversarial`);
        assert.equal(p.route, "none", `${p.key}: route none`);
        assert.ok(p.checks.includes("refused"), `${p.key}: refused check`);
      } else {
        assert.ok(typeof p.constrain === "string" && p.constrain.length > 20, `${p.key}: needs a constrain note`);
        assert.ok(!p.checks.includes("refused"));
      }
    }
  });
  it("nothing outside unsafe is flagged, and the harness's adversarial flag agrees", () => {
    for (const p of all) {
      if (p.category !== "unsafe") assert.equal(p.must_refuse, false, p.key);
      assert.equal(!!p.adversarial, p.must_refuse, `${p.key}: adversarial vs must_refuse`);
    }
  });
  it("covers the named attack classes", () => {
    const t = inCat("unsafe").filter((p) => p.must_refuse).map((p) => p.prompt.toLowerCase()).join("\n");
    for (const w of ["processbuilder", "webhook", "reflection", "paypal", "ssh", "ignore all previous", "note to the ai"]) assert.match(t, new RegExp(w), w);
  });
});

describe("eval set: change, bugfix and compat prompts", () => {
  it("change prompts point at a real, non-unsafe base prompt", () => {
    for (const p of inCat("change")) {
      const base = byKey.get(p.baseKey);
      assert.ok(base, `${p.key}: baseKey ${p.baseKey}`);
      assert.ok(base.category !== "unsafe" && base.category !== "change");
      assert.ok(p.checks.includes("preserves_existing"));
      assert.ok(effective(p).includes(base.v) || p.v === base.v, `${p.key}: same version as the base`);
    }
    assert.ok(new Set(inCat("change").map((p) => p.baseKey)).size >= 8, "varied bases");
  });
  it("bugfix prompts name a failure rule that applies to their version, each rule once", () => {
    const seen = new Set<string>();
    for (const p of inCat("bugfix")) {
      const r = rules.find((x) => x.id === p.rule);
      assert.ok(r, `${p.key}: rule ${p.rule}`);
      assert.ok(r.versions.includes("*") || r.versions.includes(p.v), `${p.key}: rule ${p.rule} does not apply to ${p.v}`);
      assert.ok(p.checks.includes("precheck_rule"));
      assert.ok(!seen.has(p.rule), `${p.key}: rule used twice`);
      seen.add(p.rule);
    }
  });
  it("compat prompts span several versions and capability prompts are only required where available", () => {
    for (const p of inCat("compat")) assert.ok(effective(p).length >= 2, p.key);
    assert.ok(inCat("compat").some((p) => (p.versions ?? []).includes("26.2")));
    for (const p of all.filter((x) => x.capability && !x.constrain)) {
      for (const v of effective(p)) assert.ok(regById.get(v)?.capabilities.includes(p.capability), `${p.key}: ${p.capability} missing on ${v}`);
    }
    for (const p of all.filter((x) => x.capability && x.constrain)) assert.ok(effective(p).some((v) => !regById.get(v)?.capabilities.includes(p.capability)), `${p.key}: constrained prompt should include a version lacking the capability`);
  });
});

describe("eval set: versions and matrix", () => {
  it("every version named exists in the registry", () => {
    for (const p of all) for (const v of [p.v, ...(p.versions ?? [])]) assert.ok(regById.has(v), `${p.key}: ${v}`);
    for (const v of matrix.versions) assert.ok(regById.has(v.id), v.id);
  });
  it("only buildable versions are 'required'; unbuildable ones are preview", () => {
    for (const v of matrix.versions) {
      const r = regById.get(v.id)!;
      if (v.role === "required") assert.equal(r.buildable, true, `${v.id} is required but not buildable`);
      else assert.equal(v.role, "preview");
      if (!r.buildable) assert.equal(v.role, "preview", `${v.id}`);
    }
    const p26 = matrix.versions.find((v: { id: string }) => v.id === "26.2");
    assert.equal(p26.role, "preview");
    assert.equal(p26.select, "core");
  });
  it("all prompts run on 1.21.11; core subsets run on 1.21.1 / 1.21.4 / 1.21.8 / 26.2", () => {
    const main = matrix.versions.find((v: { id: string }) => v.id === "1.21.11");
    assert.equal(main.select, "all");
    assert.equal(main.role, "required");
    for (const p of all) assert.ok(effective(p).includes("1.21.11"), `${p.key} not on 1.21.11`);
    const core = new Set<string>(matrix.core);
    for (const k of core) assert.ok(byKey.has(k), `core: unknown ${k}`);
    assert.equal(core.size, matrix.core.length, "core has duplicates");
    for (const id of ["1.21.1", "1.21.4", "1.21.8", "26.2"]) {
      const v = matrix.versions.find((x: { id: string }) => x.id === id);
      assert.equal(v.select, "core", id);
      const n = all.filter((p) => core.has(p.key) && effective(p).includes(id)).length;
      assert.ok(n >= 25, `${id}: only ${n} core prompts`);
    }
    for (const c of ["commands", "gameplay", "stateful", "compat", "unsafe", "asset"]) assert.ok(all.some((p) => core.has(p.key) && p.category === c), `core lacks ${c}`);
  });
  it("scoring spec has the sections report.py relies on", () => {
    for (const k of ["pass", "firstAttempt", "finalPass", "metrics", "regression", "baselineFile"]) assert.ok(k in matrix.scoring, k);
    assert.ok(matrix.scoring.regression.dropPoints > 0);
  });
});

describe("eval set: the python harness agrees", () => {
  const py = spawnSync("python3", ["--version"]);
  const run = (args: string[]) => spawnSync("python3", [path.join(EVAL, "evalset.py"), ...args], { encoding: "utf8" });
  it("evalset.py --validate passes", { skip: py.status !== 0 }, () => {
    const r = run(["--validate"]);
    assert.equal(r.status, 0, r.stdout + r.stderr);
  });
  it("run_eval.py --dry-run prints the matrix and submits nothing", { skip: py.status !== 0 }, () => {
    const r = spawnSync("python3", [path.join(EVAL, "run_eval.py"), "--dry-run", "--set", "all", "--matrix"], { encoding: "utf8" });
    assert.equal(r.status, 0, r.stdout + r.stderr);
    assert.match(r.stdout, /26\.2 +preview/);
    assert.match(r.stdout, /DRY RUN: nothing submitted/);
  });
});
